    Particle &p = particles[i];
    // Find neighbors of particle p using particleTable
    std::vector<Particle*> neighbors;
    // Assuming particleTable is a simple array or vector for demonstration
    for (uint32_t neighborIndex : particleTable[i]) {
        neighbors.push_back(&particles[neighborIndex]);
    }

    // Calculate density for particle p
    float density = mass * p.getDensity(); // Assuming getDensity() exists

    // Calculate pressure force
    float pressureForce = 0.0f;
    for (Particle* neighbor : neighbors) {
        float r = distance(p.getPosition(), neighbor->getPosition());
        float q = r / h;
        if (q < 1) {
            pressureForce += mass * (density - neighbor->getDensity()) * spikyGrad * (1 - q) / (r * r);
        }
    }

    // Calculate viscosity force
    float viscosityForce = 0.0f;
    for (Particle* neighbor : neighbors) {
        float r = distance(p.getPosition(), neighbor->getPosition());
        float q = r / h;
        if (q < 1) {
            viscosityForce += viscosity * mass * (p.getVelocity() - neighbor->getVelocity()) * spikyLap * (1 - q) / (r * r);
        }
    }

    // Update forces for particle p
    p.setForce(pressureForce + viscosityForce); // Assuming setForce() exists
}

